export interface CalculateTotalsRequest
  extends CalculateTotalsRequestCouponOneOf,
    CalculateTotalsRequestGiftCardOneOf {
  /** Coupon ID. */
  couponId?: string | null;
  /** Coupon code. */
  couponCode?: string | null;
  /**
   * DEPRECATED: Use gift_cards instead.
   * @deprecated DEPRECATED: Use gift_cards instead.
   * @replacedBy gift_cards
   * @targetRemovalDate 2026-12-01
   */
  giftCardCode?: string | null;
  /**
   * Calculation ID. An identifier of the entity that you are calculating totals for, for example, cart ID or checkout ID.
   * This value will be used in order to optimise calculations by caching.
   * If not passed, calculation might be slower in some cases.
   * @minLength 1
   * @maxLength 100
   */
  calculationId?: string | null;
  /**
   * Line items for calculation.
   * @maxSize 300
   */
  lineItems?: LineItem[];
  /** Shipping address for tax and shipping calculation (if applicable). */
  shippingAddress?: Address;
  /** Billing address. Used for calculating tax if all the items in the cart are not shippable. */
  billingAddress?: Address;
  /** Details about selected shipping option. */
  selectedShippingOption?: SelectedShippingOption;
  /**
   * Buyer email. Used to enforce coupon [single-use per customer](https://support.wix.com/en/article/wix-stores-limiting-coupon-usage). If not passed, single coupon usage per customer will not be enforced.
   * @format EMAIL
   */
  buyerEmail?: string | null;
  /**
   * Whether to calculate tax in the calculation request.
   *
   * Default: `true`
   * @internal
   */
  calculateTax?: boolean | null;
  /**
   * Member id to use for this calculation
   * When not provided, given that the caller is a member, its member id will be used
   * Providing this require elevated permissions - ECOM.ADMIN_CALCULATE_TOTALS
   */
  memberId?: string | null;
  /**
   * The selected memberships and which line items they apply to
   * When not provided, default selection will be returned
   * You can also set it to empty selection
   * Mutually exclusive with `membership_selection` - providing both returns an INVALID_ARGUMENT error.
   */
  selectedMemberships?: SelectedMemberships;
  /**
   * Whether to calculate shipping in the calculation request.
   *
   * Default: `true`
   * @internal
   */
  calculateShipping?: boolean | null;
  /** Buyer phone number. Used to get shipping rates. */
  buyerPhone?: string | null;
  /**
   * Whether to calculate discount rules in the calculation request. If not passed, discount rules are being calculated.
   * @internal
   */
  calculateDiscountRules?: boolean | null;
  /**
   * Shipping information that will be used instead of calculated shipping info.
   * @internal
   * @maxSize 1
   */
  shippingOptions?: CarrierShippingOption[];
  /**
   * Applied discounts that will be used instead of calculated discounts.
   * @internal
   * @maxSize 320
   */
  appliedDiscounts?: AppliedDiscount[];
  /**
   * Additional Fees that will be used instead of calculated additional fees
   * @internal
   * @maxSize 100
   */
  additionalFees?: AdditionalFee[];
  /**
   * List of data that should not be fetched by Totals calculator
   * @internal
   */
  skipDataFetch?: DataFetchTypeWithLiterals[];
  /**
   * Persistent ID that correlates between the various eCommerce elements: cart, checkout, and order.
   * @format GUID
   */
  purchaseFlowId?: string | null;
  /**
   * Reference to an external resource ID. Used to link the purchase flow to a specific entity in an external system.
   * For example, a Wix Pay Link ID.
   * @maxSize 20
   */
  externalReferences?: ExternalReference[];
  /**
   * The business location ID to be used as the basis for some calculations.
   * Learn more about the [Locations API](https://dev.wix.com/docs/rest/business-management/locations/introduction).
   * @format GUID
   */
  businessLocationId?: string | null;
  /**
   * DEPRECATED: Use `giftCards.redeemAmount` instead.
   * @decimalValue options { gte:0, lte:1000000000000000, maxScale:3 }
   * @deprecated DEPRECATED: Use `giftCards.redeemAmount` instead.
   * @replacedBy gift_cards
   * @targetRemovalDate 2026-12-01
   */
  giftCardRedeemAmount?: string | null;
  /**
   * Buyer contact ID.
   * @internal
   * @format GUID
   */
  contactId?: string | null;
  /** [Extended fields](https://dev.wix.com/docs/rest/articles/getting-started/extended-fields). */
  extendedFields?: ExtendedFields;
  /**
   * Exempt group to use for tax calculations.
   * @internal
   * @format GUID
   */
  taxExemptGroupId?: string | null;
  /**
   * Controls behavior when the selected shipping option is unavailable:
   * + `true` - An alternative shipping option is automatically selected from the available options.
   * + `false` - An alternative shipping option is not automatically selected from the available options,
   * and a calculation error will be returned to signal that the selected option is unavailable.
   *
   * Default: `true`
   * @internal
   */
  selectedShippingFallback?: boolean | null;
  /**
   * Whether SPECIFIC_ITEMS discounts are applied directly to item prices.
   *
   * When `true`:
   * + SPECIFIC_ITEMS discounts reduce item `price`, which is reflected in the subtotal.
   * + GLOBAL discounts are applied on top of the subtotal, without modifying item `price`.
   *
   * When `false` (current behavior):
   * + All coupons and merchant discounts are treated as GLOBAL; item prices are unchanged.
   *
   * Note: SPECIFIC_ITEMS automatic discounts are already applied to item prices, regardless of this setting.
   *
   * Default: `false`
   * @internal
   */
  applyItemDiscountsToPrices?: boolean;
  /**
   * Gift cards to apply.
   * @internal
   * @maxSize 5
   */
  giftCards?: GiftCardInput[];
  /**
   * Membership selection (existing + future) to be validated and enhanced.
   * When set, memberships are resolved via the EnhanceAndValidateSelection SPI flow.
   * Mutually exclusive with `selected_memberships` - providing both returns an INVALID_ARGUMENT error.
   * @internal
   */
  membershipSelection?: MembershipSelection;
  /**
   * Currency of the specified amounts. When set, the calculation is performed and rounded in this currency.
   * Three-letter currency code in
   * [ISO-4217 alphabetic](https://en.wikipedia.org/wiki/ISO_4217#Active_codes) format.
   *
   * Default: The site's default currency.
   * @internal
   * @format CURRENCY
   */
  amountCurrency?: string | null;
  /**
   * ID of the site payment method type the customer selected to pay with. See the [Site Payment Method Types API](https://dev.wix.com/docs/api-reference/business-management/payments/site-payment-method-types/introduction).
   * @internal
   * @format GUID
   */
  sitePaymentMethodTypeId?: string | null;
}

