export interface LineItem {
  /**
   * Line item ID.
   * @minLength 1
   * @maxLength 100
   */
  _id?: string;
  /**
   * Quantity.
   * @max 100000
   */
  quantity?: number | null;
  /**
   * Optional references to the line item's origin catalog.
   * See [Catalog SPI](https://bo.wix.com/wix-docs/rest/ecommerce/catalog-spi/introduction) for more details.
   * This field may be empty in the case of a custom line item.
   * currently we only use the catalog app id to set tax=0 for specific apps.
   */
  catalogReference?: CatalogReference;
  /**
   * Product/booking/event name.
   * @maxLength 200
   */
  productName?: string | null;
  /**
   * Catalog price.
   * @decimalValue options { gte:0 }
   */
  price?: string;
  /** Physical properties (if applicable). */
  physicalProperties?: PhysicalProperties;
  /**
   * Coupon scopes - which app and items a coupon applies to.
   * This field is internal to Wix, and should be used by Bookings, Stores and Events as used by the current [Coupons API](https://bo.wix.com/wix-docs/rest/stores/coupons/valid-scope-values).
   * @internal
   */
  couponScopes?: Scope[];
  /**
   * Tax group ID.
   * @internal
   * @format GUID
   */
  taxGroupId?: string | null;
  /**
   * Shipping group ID.
   * @internal
   * @format GUID
   */
  shippingGroupId?: string | null;
  /** Subscription settings. */
  subscriptionSettings?: SubscriptionSettings;
  /**
   * Type of selected payment option for current item.
   *
   * Default: `FULL_PAYMENT_ONLINE`
   */
  paymentOption?: PaymentOptionTypeWithLiterals;
  /** Service properties. When relevant, this contains information such as date and number of participants. */
  serviceProperties?: ServiceProperties;
  /**
   * In cases where `catalogReference.catalogItemId` is NOT the actual catalog item ID, this field will return the true item's ID.
   * + For example, for Wix Bookings, `catalogReference.catalogItemId` is the booking ID. Therefore this value is set to the service ID.
   * + In most cases, this field has the same value as `catalogReference.catalogItemId`.
   * + Used in membership validation.
   * @minLength 1
   * @maxLength 36
   */
  rootCatalogItemId?: string | null;
  /**
   * Optional - partial amount of item's price to be paid now for checkout cases with DEPOSIT_ONLINE payment option
   * If omitted - item's price will not be split and is expected to be paid in single installment
   * @format DECIMAL_VALUE
   */
  depositAmount?: string | null;
  /**
   * full price of the item before all the discounts
   * @format DECIMAL_VALUE
   */
  fullPrice?: string | null;
  /**
   * The Item's Delivery Profile Id
   * @format GUID
   */
  deliveryProfileId?: string | null;
  /** Item type. Either a preset type or custom. */
  itemType?: ItemType;
  /** Address to use for tax calculation purposes. */
  taxableAddress?: TaxableAddress;
  /**
   * Additional Fees to be added to used for calculation.
   * @readonly
   * @maxSize 5
   */
  additionalFees?: ApiV1AdditionalFee[];
  /**
   * Modifier groups that were added to the item.
   * @maxSize 25
   */
  modifierGroups?: ModifierGroup[];
  /**
   * Platform fee that should be charged for the item.
   * @internal
   */
  platformFee?: PlatformFee;
}

/** Used for grouping line items. Sent when an item is added to a cart, checkout, or order. */
export interface CatalogReference {
  /**
   * ID of the item within the catalog it belongs to.
   * @minLength 1
   * @maxLength 36
   */
  catalogItemId?: string;
  /**
   * ID of the app providing the catalog.
   *
   * You can get your app's ID from its page in the [app dashboard](https://dev.wix.com/dc3/my-apps/).
   *
   * For items from Wix catalogs, the following values always apply:
   * + Wix Stores: `"215238eb-22a5-4c36-9e7b-e7c08025e04e"`
   * + Wix Bookings: `"13d21c63-b5ec-5912-8397-c3a5ddb27a97"`
   * + Wix Restaurants: `"9a5d83fd-8570-482e-81ab-cfa88942ee60"`
   * @minLength 1
   */
  appId?: string;
  /**
   * Additional item details in `key:value` pairs.
   *
   * Use this optional field for more specificity with item selection. The values of the `options` field differ depending on which catalog is providing the items.
   *
   * For Wix Stores products, learn more about integrating with [Catalog V3](https://dev.wix.com/docs/api-reference/business-solutions/stores/catalog-v3/e-commerce-integration)
   * or [Catalog V1](https://dev.wix.com/docs/api-reference/business-solutions/stores/catalog-v1/catalog/e-commerce-integration), depending on [the version the site uses](https://dev.wix.com/docs/api-reference/business-solutions/stores/catalog-versioning/introduction).
   */
  options?: Record<string, any> | null;
}

