/**
 * A single redeemable benefit granted by a plan.
 *
 * A purchasable plan grants one or more benefits in `benefits`. Once the plan is paid for, each benefit
 * becomes its own membership, charged by `membershipId`.
 */
export interface Benefit extends BenefitQuotaOneOf {
  limitedQuota?: LimitedQuota;
  /**
   * Identifier for this benefit, unique within its plan.
   *
   * Not unique across the response. A plan is returned once per pricing variant, and every variant
   * repeats that plan's benefit IDs. Two different plans can also share an ID when they grant the
   * same benefit, and a coverage entry naming it is then true for both.
   *
   * Never give two different benefits the same ID. That's the one case a caller can't recover from,
   * because a cost computed for one benefit would be applied to the other.
   * @minLength 1
   * @maxLength 200
   */
  benefitId?: string;
  /**
   * Human-readable label for this benefit. For example, `Manicure` or `Pedicure` on a multi-set
   * punch card.
   * @maxLength 200
   */
  label?: string | null;
  /** Kind of quota this benefit grants. */
  quotaType?: QuotaTypeWithLiterals;
}

/** @oneof */
export interface BenefitQuotaOneOf {
  limitedQuota?: LimitedQuota;
}

export enum QuotaType {
  /** The benefit grants a countable quota that's drawn down on redemption. */
  LIMITED = 'LIMITED',
  /** The benefit is unlimited and is never drawn down. */
  UNLIMITED = 'UNLIMITED',
}

/** @enumType */
export type QuotaTypeWithLiterals = QuotaType | 'LIMITED' | 'UNLIMITED';

/** A limited, countable redeemable amount. */
export interface LimitedQuota {
  /**
   * Quota's initial value.
   * @min 1
   */
  total?: number;
  /** Quota's remaining value. */
  remaining?: number;
  /**
   * How the quota is measured.
   *
   * The same vocabulary as `MembershipPaymentCredits.balanceType` on the existing-membership side.
   */
  limitedQuotaType?: LimitedQuotaTypeWithLiterals;
}

export enum LimitedQuotaType {
  /** Quota is measured in discrete uses, such as sessions or visits. */
  PUNCH_CARD = 'PUNCH_CARD',
  /** Quota is measured in a currency-like value, such as points. */
  CREDIT = 'CREDIT',
}

/** @enumType */
export type LimitedQuotaTypeWithLiterals =
  | LimitedQuotaType
  | 'PUNCH_CARD'
  | 'CREDIT';

/**
 * Maps one of a plan's benefits to a line item it can cover, and at what cost.
 *
 * One entry per benefit and line item pair, returned by [List Purchasable Plans](https://dev.wix.com/docs/api-reference/business-solutions/e-commerce/payments/memberships/memberships-service-plugin/list-purchasable-plans) alongside `purchasablePlans`.
 *
 * An entry names a benefit and carries no plan identity, so match its `benefitId` against the
 * `benefits` of the returned plans and apply it to every entry that grants that benefit. Entries for
 * the same plan repeat it once per pricing variant, and two different plans sharing a benefit ID
 * grant the same benefit, so the entry holds for each of them. A caller that stops at the first
 * match shows nothing incorrect, but hides the other entries, which cover the item too.
 *
 * The cost is identical across a plan's variants, so there's one entry per benefit rather than one
 * per variant.
 *
 * For memberships the member already owns, the equivalent mapping is
 * `ExistingMembership.coveredLineItems`, which needs no `benefitId` because a membership is a single
 * benefit.
 */
export interface LineItemCoverage {
  /**
   * ID of the benefit that covers the line item, as returned in `Benefit.benefitId`.
   *
   * Identifies a benefit within its plan, and repeats across that plan's pricing variants.
   * @minLength 1
   * @maxLength 200
   */
  benefitId?: string;
  /**
   * ID of the line item this benefit covers.
   * @minLength 1
   * @maxLength 100
   */
  lineItemId?: string;
  /**
   * Amount deducted from the benefit's `limitedQuota.remaining` value when this line item is redeemed.
   *
   * Always `0` for an unlimited benefit, which decrements nothing.
   */
  redemptionCost?: number;
}

